import{c as e,Q as o,j as r,m as a}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Resolving issues on the day","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/resolving-issues.md","filePath":"user/running-the-event/resolving-issues.md"}'),n={name:"user/running-the-event/resolving-issues.md"};function s(i,t,h,d,l,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="resolving-issues-on-the-day" tabindex="-1">Resolving issues on the day <a class="header-anchor" href="#resolving-issues-on-the-day" aria-label="Permalink to &quot;Resolving issues on the day&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators dealing with problems during the event.</p><p>Recipes for the things that commonly go wrong during a live event. Each is a short <strong>symptom → fix</strong>. Most fixes live on the <strong>competitor&#39;s record</strong> or the <strong>control&#39;s record</strong>, so two moves cover the majority of them:</p><ul><li><strong>Open a competitor</strong> — click their name in the <a href="./../event-setup/competitors-clubs-teams">Competitors list</a>, in the download history on the <a href="./card-download">Card downloads</a> page, or via <strong>Quick competitor actions</strong> on the <a href="./dashboard">dashboard</a>. Inside the dialog, <strong>Ctrl+F</strong> (<strong>⌘F</strong> on a Mac) jumps to another competitor without closing it.</li><li><strong>Open a control</strong> — click it on the <a href="./../event-setup/controls-and-radio-controls">Controls page</a> to reach the <strong>Edit Control</strong> dialog.</li></ul><blockquote><p><strong>Tip:</strong> Manager re-evaluates results automatically after a fix — change a start time, status, class, or punch and the race time and standings update within a few seconds. There&#39;s no separate recalculate step.</p></blockquote><h2 id="the-competitor-s-tabs" tabindex="-1">The competitor&#39;s tabs <a class="header-anchor" href="#the-competitor-s-tabs" aria-label="Permalink to &quot;The competitor&#39;s tabs&quot;">​</a></h2><p>The <strong>Edit competitor</strong> dialog has a tab for each kind of fix. Some only appear when they have something to show.</p><table tabindex="0"><thead><tr><th>Tab</th><th>Use it to</th></tr></thead><tbody><tr><td><strong>Details</strong></td><td>Correct the name, club, <strong>Card number</strong>, class and course</td></tr><tr><td><strong>Start</strong></td><td>See where the start time comes from, and set an <strong>Allocated start time</strong> or how a start punch is treated (<strong>On start punch</strong>). Not shown for a relay runner, whose start is the changeover</td></tr><tr><td><strong>Result</strong></td><td>Read the status, race time and place, and set the <strong>Status</strong> by hand. Also gives a runner with <em>No start time</em> a start</td></tr><tr><td><strong>Radio punches</strong></td><td>See every radio punch for them, and delete a spurious one</td></tr><tr><td><strong>Download</strong></td><td>See the card read, choose between several, and make or edit a <a href="./card-download#manual-downloads">manual download</a></td></tr><tr><td><strong>Unit downloads</strong></td><td>See what the Start, Check and Finish units&#39; <a href="./station-memory">station memory</a> recorded for them</td></tr><tr><td><strong>Prints</strong></td><td>Preview and reprint their <a href="./splits-printing#printing-by-hand-and-reprinting">splits or result label</a></td></tr><tr><td><strong>Analysis</strong></td><td>Their mistakes and strong legs. Not offered on a course run in any order (score and scatter courses)</td></tr><tr><td><strong>Overrides</strong></td><td>Correct the punches: start and finish times, a missed control, a stale punch, a time penalty. A badge counts the overrides in force</td></tr><tr><td><strong>Audit trail</strong></td><td>Everything that was changed about them, when and from where — see <a href="./../reference/audit-trail#one-competitor-s-history">Audit trail</a></td></tr><tr><td><strong>Custom fields</strong>, <strong>Hire items</strong></td><td>Only when you have set some up in Settings</td></tr></tbody></table><h2 id="competitor-results" tabindex="-1">Competitor results <a class="header-anchor" href="#competitor-results" aria-label="Permalink to &quot;Competitor results&quot;">​</a></h2><p><strong>Still &quot;On course&quot; long after they finished.</strong> Their card hasn&#39;t been downloaded and no radio finish has arrived, so Manager still thinks they&#39;re out. Download their card — that produces the authoritative result. If they crossed a <em>radio</em> finish but haven&#39;t downloaded yet, they already show as a preliminary <strong>OK</strong> (the <strong>Pending</strong> count on the dashboard) and will finalise when the card is read. If they retired or have no card, set the status by hand (below). See <a href="./safety-check">Safety check</a>.</p><p><strong>A finish but no start time.</strong> Race time can&#39;t be worked out without a start. Give the competitor a start time — an allocated start on their <strong>Start</strong> tab, or a punched start if you run punching starts. See <a href="./../event-setup/start-times">Start times</a>.</p><p><strong>A status that&#39;s wrong, or you need to disqualify.</strong> Open the competitor, go to the <strong>Result</strong> tab, and change the <strong>Status</strong>. The choices are <strong>None</strong>, <strong>On course</strong>, <strong>OK</strong>, <strong>MP</strong>, <strong>DNF</strong>, <strong>DNS</strong>, <strong>Not competing</strong>, <strong>Disqualified</strong>, <strong>Out of competition</strong> and <strong>Overtime</strong>. Most are free operator rulings and stick as you set them: later re-evaluations — a control edit, a class change, an added punch override — recompute the times but leave your status alone. Beside the status the tab says <strong>Manual</strong> for a status you set and <strong>Set automatically</strong> for one Manager worked out, and the Competitors list shows a hand icon beside a status set by hand. Click <strong>Auto</strong> beside the status to hand it back to Manager, which works it out again from the card or the radio punches.</p><p><strong>OK is the exception:</strong> you can&#39;t force it on a competitor whose card doesn&#39;t support a clean result. Manager re-evaluates OK against the punches, so setting it on someone still missing a control is corrected straight back to <strong>MP</strong> (and OK always needs a race time). This is enforced on the server, so it can&#39;t be bypassed from the screen.</p><p><strong>Approving a run with a missed control.</strong> When the jury or the organiser accepts a run the card says is incomplete — the control was misplaced, the unit failed for this runner, the card failed — don&#39;t set OK. Open the <strong>Overrides</strong> tab, find the leg reading <strong>No punch</strong>, click <strong>Mark visited</strong>, and give a <strong>Reason</strong> (<em>Control miss-placed</em>, <em>Electronic punch failed</em>, <em>Card failed</em>, <em>Lost/damaged card</em>, or your own words). The control now counts as visited, the card re-evaluates, and the <strong>OK</strong> follows by itself. A control marked visited has no punch time, so that leg has no split. If the control failed for <em>everyone</em>, mark the control <strong>Faulty</strong> instead (see <a href="#controls-and-hardware">Controls and hardware</a>).</p><blockquote><p><strong>Note:</strong> Manager won&#39;t let you reset a competitor to <strong>None</strong> (no result) while there&#39;s real evidence they took part — a recorded race time, a downloaded card, a start punch, or radio punches. It tells you which evidence is blocking the reset, so you don&#39;t accidentally erase a genuine result. Clear the evidence (e.g. unassign the stray download) first if you really mean to.</p></blockquote><p><strong>Card reads but the competitor isn&#39;t in the list.</strong> Assign the download to an existing competitor, or add a new one, right from the <a href="./card-download#fast-fixes-right-after-a-download">Card downloads</a> page. The same handles a <strong>wrong hire card</strong> — assign the download to whoever actually ran it.</p><p><strong>Wrong course or class, after the download has scrolled off screen.</strong> Open the download&#39;s detail dialog from the history table and use <strong>Change class/course</strong> to re-check it against the right one, or change the <strong>Class</strong> (and <strong>Course</strong>) on the competitor&#39;s <strong>Details</strong> or <strong>Result</strong> tab. See <a href="./card-download#the-card-download-detail-dialog">Downloading cards</a>.</p><p><strong>A runner shows Not competing with <em>No start time</em>.</strong> They completed the course, but nothing says when they started — the Start unit failed, or they didn&#39;t punch it — and the event doesn&#39;t guess from the check punch or midnight. Give them a start time: on the download desk&#39;s panel straight after the read — type the time, or press <strong>Use check punch</strong> to start them at their check punch — or any time later from their <strong>Result</strong> tab, or as a start override on their <strong>Overrides</strong> tab. If a whole start went unpunched and the check is close enough, you can instead turn the <a href="./../reference/status-and-race-time#a-runner-with-no-start-time">no-start-time fallback</a> on for the event (<strong>Starts</strong> tab of its <strong>Event details</strong>) and every such runner is timed from their check punch at once. If the course had no start unit at all, it can take its start from its first control instead: see <a href="./../event-setup/classes-and-courses#starting-or-finishing-at-a-numbered-control">Starting or finishing at a numbered control</a>.</p><h3 id="typing-a-time-in-by-hand" tabindex="-1">Typing a time in by hand <a class="header-anchor" href="#typing-a-time-in-by-hand" aria-label="Permalink to &quot;Typing a time in by hand&quot;">​</a></h3><p>Which time you type, and where, depends on what is wrong:</p><ul><li><strong>The start they were meant to have</strong> — their <strong>Start</strong> tab, <strong>Allocated start time</strong>. This is the start list, not a correction: a start punch can still win over it, depending on <strong>On start punch</strong>. See <a href="./../event-setup/start-times">Start times</a>.</li><li><strong>The start they actually had</strong>, when the punched or allocated one is wrong — the <strong>Overrides</strong> tab, <strong>Start</strong> row, <strong>Override</strong>. An override beats every other source of a start time.</li><li><strong>The finish</strong> — the <strong>Overrides</strong> tab, <strong>Finish</strong> row, <strong>Override</strong>. Use this when the finish unit misbehaved, or a runner reached the line without punching and you have their time from elsewhere (a radio finish, the finish unit&#39;s <a href="./station-memory">station memory</a>, a stopwatch).</li><li><strong>The whole run</strong>, when there&#39;s no card read at all — a <a href="./card-download#manual-downloads">manual download</a> on their <strong>Download</strong> tab.</li></ul><p>Each time override takes a <strong>Time of day</strong> and an optional reason, and is listed with an <strong>Edit</strong> button and a <strong>×</strong> to remove it. The <strong>Check</strong> row has no time override: a check punch can only be excluded or included.</p><h3 id="editing-the-punches-on-a-downloaded-card" tabindex="-1">Editing the punches on a downloaded card <a class="header-anchor" href="#editing-the-punches-on-a-downloaded-card" aria-label="Permalink to &quot;Editing the punches on a downloaded card&quot;">​</a></h3><p>The <strong>Overrides</strong> tab is where you correct what the card says without changing the card itself. It appears once the competitor has a card read, an override already in force, or a race time to adjust; otherwise it says overrides are only available once their card has been downloaded. If their class has a pool of courses and none has been chosen yet, control overrides are disabled until a course is picked on <strong>Details</strong> or a download arrives.</p><p>At the top, a table of <strong>Start</strong>, <strong>Check</strong>, <strong>Finish</strong> and <strong>Race time</strong> — each with the time the card gave, any override, and its actions. Below it, <strong>Punches</strong>: one table in course order, every leg of the course with the punch that counted for it, and the card&#39;s other punches between them, each with a <strong>Status</strong> — <strong>Included</strong>, <strong>Excluded</strong>, <strong>Manual override</strong> (a control marked visited), <strong>No punch</strong> or <strong>Not on course</strong>. From here you can:</p><ul><li><strong>Mark visited</strong> a leg with <strong>No punch</strong>, with a reason — and <strong>Remove</strong> that again.</li><li><strong>Exclude</strong> any punch the card carries, with a reason — and <strong>Include</strong> it again.</li><li><strong>Override</strong> the start or finish time (above), or the race time (below).</li><li><strong>Delete all overrides</strong>, at the foot of the tab, to put everything back to what the card says.</li></ul><p>Hover over the small note icon beside an override to read the reason given. Nothing on this tab changes the card download itself — the <strong>Download</strong> tab and the <a href="./card-download">Card downloads</a> page still show every punch the chip physically held.</p><h3 id="a-card-that-still-holds-a-previous-run" tabindex="-1">A card that still holds a previous run <a class="header-anchor" href="#a-card-that-still-holds-a-previous-run" aria-label="Permalink to &quot;A card that still holds a previous run&quot;">​</a></h3><p><strong>The runner forgot to clear and check, so their card still holds a previous run.</strong> This is the case exclusions exist for. The old punches are still on the chip, and because Manager matches punches to controls in order, it consumes the <em>stale</em> ones first — so every split is wrong, this run&#39;s punches pile up as extras, and worse, a leftover <strong>Check</strong> silently becomes the start of the race while a leftover <strong>Finish</strong> fabricates a finish time.</p><p>Open the competitor&#39;s <strong>Overrides</strong> tab. Every punch the card holds is listed with its time of day, under <strong>Punches</strong>, alongside the <strong>Start / Check / Finish</strong> table at the top. Work out which punches belong to the previous run — the times give it away, usually a clean block an hour or more before the real start — and click <strong>Exclude</strong> on each, choosing a reason (<em>Card not cleared</em>, <em>Punched wrong control</em>, or your own words) if you want one recorded. Everything re-evaluates as you go.</p><p>An excluded punch reads exactly as one the card never carried: it&#39;s never matched to a control, never produces a split, never counts as an extra. Excluding the <strong>Start</strong> drops the competitor back to their allocated start time; excluding the <strong>Finish</strong> leaves them <strong>DNF</strong> until you enter the real finish time as an override. Excluding a stale punch also stops Manager offering you a &quot;did they run a different class?&quot; suggestion that isn&#39;t the real remedy.</p><blockquote><p><strong>Watch the start time after excluding a Start or Check punch.</strong> Those two are rungs on the <a href="./../reference/status-and-race-time#how-race-time-is-calculated">start-time cascade</a>, so removing them hands the start to whatever is next — and if the competitor has <em>no allocated start time</em> either, the cascade runs out. With the <a href="./../reference/status-and-race-time#a-runner-with-no-start-time">no-start-time fallback</a> on, Manager then measures from midnight, which makes the race time equal to the finish punch&#39;s time of day (a runner finishing at 08:36 reads as a race time of 516:08) while the status still shows <strong>OK</strong> — a placing you don&#39;t want in your results. Manager flags such a runner (<em>No start punch</em>), but make sure the competitor has an allocated start time, or set a <strong>start time override</strong> on the same tab. With the fallback switched off, they show as <strong>Not competing</strong> with <em>No start time</em> instead, so there&#39;s no placing to miss.</p><p>The reverse can also fool you: if the allocated start happens to match the punch you excluded — common when start times were generated from the punches themselves — the time won&#39;t visibly change at all. Check the <strong>source label</strong> beside the start time on the <strong>Result</strong> tab (<em>start punch</em>, <em>allocated start</em>, <em>class mass start</em>, <em>event mass start</em>, <em>check punch</em>) rather than the number: it tells you which rung the time actually came from.</p></blockquote><p>Nothing is erased. The <strong>Download</strong> tab and the <a href="./card-download">Card downloads</a> page still show every punch the chip physically held — the card stays the record of what happened, and the exclusion is your judgement layered on top. Changed your mind? Click <strong>Include</strong> to put a punch back.</p><blockquote><p><strong>Note:</strong> an exclusion is tied to the exact punch on the card it was made against. If you later assign the competitor a <em>different</em> download, exclusions that don&#39;t match anything on the new card stop having any effect, and are listed at the bottom of the punches table under <strong>No longer on this card</strong> so you can clear them out.</p></blockquote><h3 id="time-penalties-and-time-credits" tabindex="-1">Time penalties and time credits <a class="header-anchor" href="#time-penalties-and-time-credits" aria-label="Permalink to &quot;Time penalties and time credits&quot;">​</a></h3><p><strong>A runner should lose time, or get time back</strong> — a penalty the jury awarded, or a runner held at a road crossing or by an incident on the course. Open the <strong>Overrides</strong> tab and, on the <strong>Race time</strong> row, click <strong>Override</strong>. Enter the <strong>Time adjustment (s)</strong> in seconds — positive adds a penalty, negative credits time back — and a <strong>Reason</strong>, which is required. The dialog shows the <strong>New adjusted time</strong> before you save.</p><p>That adjusted time is what the runner is ranked, exported and published on; the <strong>Result</strong> tab shows it as <strong>Adjusted time</strong> beside the clock time. It can only be set on a competitor who has a race time. To take it off, remove it from the same row.</p><p>For a delay that affected <em>everyone</em> on a leg — a road crossing, a hold at a bridge — use an <a href="#a-leg-that-should-not-count">untimed leg</a> instead of adjusting each runner.</p><h3 id="lost-cards-and-shared-cards" tabindex="-1">Lost cards and shared cards <a class="header-anchor" href="#lost-cards-and-shared-cards" aria-label="Permalink to &quot;Lost cards and shared cards&quot;">​</a></h3><p><strong>A card was lost, so there&#39;s nothing to download.</strong> Open the competitor and, on the <strong>Download</strong> tab, click <strong>New manual download…</strong>. Type in their start, finish and control times — from the finish unit, the <a href="./station-memory">station memory</a> or their radio punches — and <strong>Save</strong>. Manager evaluates it exactly like a card it had read. See <a href="./card-download#manual-downloads">Manual downloads</a>.</p><p><strong>Two runners went round together on one card.</strong> Open the runner who didn&#39;t have the card and, on the <strong>Download</strong> tab, click <strong>New manual download…</strong>, then pick their partner&#39;s download under <strong>Copy from a download</strong>. Save, and both get the run — the partner&#39;s download stays exactly as it was. A manual download can only be made for a runner with no download, so if they also read a card of their own that has nothing of the run on it, unassign or delete that read first. See <a href="./card-download#manual-downloads">Manual downloads</a>.</p><p><strong>A card number was typed wrong.</strong> Correct the <strong>Card number</strong> on the competitor&#39;s <strong>Details</strong> tab (or with <strong>Set card</strong> in <strong>Quick competitor actions</strong>). Everything the card number is the key to follows the correction: a card read waiting unassigned for the new number is assigned to them and scored, radio punches already stored for that card become theirs, and anything the old number put on them — a read, a punched start — is taken back. You don&#39;t have to re-read the card.</p><p><strong>Two runners swapped cards</strong>, so each download landed on the other person. Open each download&#39;s detail dialog (click the card number in the history table) and <strong>Unassign</strong> it, then correct the <strong>Card number</strong> on both competitors. Each picks up the read of the card they now hold by itself. If a read doesn&#39;t attach, the <strong>Card downloads</strong> page counts it among the cards to assign: open it and <strong>Assign</strong> it to the right runner. If both ran with the same card at different times, see <a href="./who-is-still-on-course#more-than-one-run-on-a-card">More than one run on a card</a>.</p><blockquote><p><strong>Note:</strong> Assigning a read to somebody who already has one asks first, then takes their old read off them and clears their result. Assigning a card that was on somebody else does the same to them. Manager says so on the Card downloads page, and the released read waits to be assigned again.</p></blockquote><h3 id="stray-radio-punches" tabindex="-1">Stray radio punches <a class="header-anchor" href="#stray-radio-punches" aria-label="Permalink to &quot;Stray radio punches&quot;">​</a></h3><p><strong>A radio punch is wrong</strong> — a unit double-reporting, an official testing a control, a phantom read keeping a card on the On course list. On the Competitors list, the punch shows in the competitor&#39;s <strong>Last seen</strong> chip: <strong>Suppress</strong> it from there. A suppressed punch is kept and greyed out, is ignored by the Leaderboard and the predicted positions, and can be reinstated at any time. To get rid of a punch outright, delete it — from the trash icon on the competitor&#39;s <strong>Radio punches</strong> tab, or the <strong>delete radio punches</strong> action in the <a href="./who-is-still-on-course#the-on-course-dialog">On course or Pending dialogs</a>. A deleted punch can&#39;t be recovered, and the competitor is re-evaluated from the punches left. See <a href="./radio-punches">Radio punches</a>.</p><h2 id="controls-and-hardware" tabindex="-1">Controls and hardware <a class="header-anchor" href="#controls-and-hardware" aria-label="Permalink to &quot;Controls and hardware&quot;">​</a></h2><p><strong>A control&#39;s clock was off — all its punches are shifted.</strong> Open the control and set a <strong>Time Offset</strong>: a <code>+</code> or <code>−</code> correction in hours, minutes and seconds that is <em>added</em> to every punch time it recorded, so a unit running two minutes fast needs <code>−</code> 00:02:00. It&#39;s applied to every punch recorded against that control — card downloads and radio punches alike — and retrospectively, so fixing it after downloads have come in re-times the affected punches. Start, Finish and Check controls have the tab too. See <a href="./../event-setup/controls-and-radio-controls#time-offset">Time Offset</a>.</p><p>Three places tell you a clock is wrong:</p><ul><li><strong>For a control with a meshO Control radio</strong>, Manager estimates the error from the time each radio punch was stamped against the time it arrived. The Controls page&#39;s <strong>Clock</strong> column shows it, anything over five seconds is highlighted there and raised as a dashboard alert (<em>Control … has a clock error of …</em>), and the control&#39;s <strong>Clock</strong> tab shows the punches behind the figure with a <strong>Use suggested offset</strong> button that sets the Time Offset for you. Punches that all arrived together after a radio outage say nothing about the clock, so the tab waits for one that arrives on its own before suggesting anything.</li><li><strong>For any SportIdent unit you can reach with a reader</strong>, the <strong>Station clock</strong> on the <a href="./station-memory#the-station-clock">Station memory</a> or <a href="./../reference/station-configuration#the-station-clock">Station configuration</a> screen shows how far its clock is ahead of or behind this computer (<strong>Drift vs PC</strong>).</li><li><strong>On a card</strong>, a control whose punch times are out of sequence with the controls either side of it.</li></ul><p>Correct the punches with the Time Offset rather than changing the unit&#39;s clock part-way through the event — changing the clock leaves the punches already made wrong.</p><p><strong>A control unit failed and was swapped for one with a different number.</strong> Open the control and set its <strong>Replacement code</strong> (on the <strong>Replacement</strong> tab) so punches on the new number count as the original control. See <a href="./../event-setup/controls-and-radio-controls#renumbered-or-swapped-controls">Renumbered or swapped controls</a>.</p><p><strong>A control unit died and wasn&#39;t replaced.</strong> Open the control and mark it <strong>Faulty</strong> (on the <strong>Faulty</strong> tab). A faulty control is never required, so competitors aren&#39;t penalised with a missing punch for a control that wasn&#39;t working — on every course, for downloads already read as well as those still to come. It keeps its place in the course, so splits, exports and analysis still line up with the control numbers on their map. Marking a control faulty clears its replacement code and time offset. See <a href="./../event-setup/controls-and-radio-controls#faulty-normal-only">Faulty controls</a>.</p><p><strong>The start or finish unit is the one missing.</strong> <strong>Faulty</strong> is for numbered controls only. A course can instead take its start from its first control, or its finish from its last, so the run is timed between those punches: see <a href="./../event-setup/classes-and-courses#starting-or-finishing-at-a-numbered-control">Starting or finishing at a numbered control</a>. For a few runners whose finish punch is missing, a finish time override is simpler (see <a href="#typing-a-time-in-by-hand">Typing a time in by hand</a>).</p><p><strong>A control was out of place for some runners only</strong> — moved, vandalised, or put out late. Leave the control as it is and <a href="#competitor-results">approve each affected run</a> by marking the control visited on their <strong>Overrides</strong> tab, with the reason <em>Control miss-placed</em>.</p><p><strong>A radio control stopped reporting, or forwarding dropped.</strong> The dashboard&#39;s <strong>Radio controls</strong> tile flags a control that&#39;s gone quiet, and the <strong>Radio punch forwarding</strong> tile shows whether punches are still being forwarded. Punches the radio missed still arrive with the card download, and a unit&#39;s own memory can be read afterwards — see <a href="./radio-punches#recovering-missed-punches">Recovering missed punches</a>.</p><p><strong>The computer running the event failed.</strong> If a <a href="./live-standby">live standby</a> is following the event, press <strong>Take over the event</strong> on it and work through its handover list. Without one, restore the newest backup on another computer and resume it; see <a href="./../event-setup/moving-an-event#if-the-event-is-already-live">If the event is already live</a>.</p><h2 id="the-course-and-the-start" tabindex="-1">The course and the start <a class="header-anchor" href="#the-course-and-the-start" aria-label="Permalink to &quot;The course and the start&quot;">​</a></h2><h3 id="a-leg-that-should-not-count" tabindex="-1">A leg that should not count <a class="header-anchor" href="#a-leg-that-should-not-count" aria-label="Permalink to &quot;A leg that should not count&quot;">​</a></h3><p><strong>A leg has to be taken out of the timing</strong> — a road crossing runners must walk, a dangerous leg the jury voids, a hold at a marshalled crossing. Open <strong>Event data → Legs</strong>, click the leg (the pair of controls), and set an <strong>Untimed time</strong> in minutes and seconds. On every card download, each runner&#39;s time for that leg is reduced by up to that amount: a runner who took less than the allowance loses the whole leg from their race time, and one who took longer keeps only the excess. To void a leg completely, give it an allowance longer than anybody took on it.</p><p>Worth knowing:</p><ul><li>The allowance belongs to the leg, not the course, so it applies to every course that runs between those two controls.</li><li>It applies only where the runner punched both ends of the leg.</li><li>It is applied to card downloads only. Live radio results — the Leaderboard and the projected times — are not adjusted.</li><li>Changing it re-scores the cards already read.</li></ul><h3 id="a-start-that-was-interrupted" tabindex="-1">A start that was interrupted <a class="header-anchor" href="#a-start-that-was-interrupted" aria-label="Permalink to &quot;A start that was interrupted&quot;">​</a></h3><p><strong>The start was held up, or the whole programme has to move.</strong> What to change depends on how far the start has got:</p><ul><li><strong>Before anyone has started</strong> — open the <strong>Start list</strong> tab of <strong>Starts</strong> and use <strong>Actions → Move all start times…</strong> to move every individual start later or earlier. Mass starts and the course closure stay where they are; change those separately. See <a href="./../event-setup/start-times#moving-every-start-time">Moving every start time</a>.</li><li><strong>Part-way through the start</strong> — <em>Move all start times</em> refuses once the first competitor has gone. Move the rest of a class on the <a href="./../event-setup/start-draw">Manage starts</a> screen, change a class&#39;s mass start on the class, or give individual runners new times on their <strong>Start</strong> tab. Runners who already started keep their times.</li><li><strong>Runners who were sent off late</strong> — at an event with punching starts their start punch already records when they really went. Otherwise give each the start they actually had as a <strong>start time override</strong> on their <strong>Overrides</strong> tab.</li><li><strong>Runners stopped on the course</strong> — credit the time they lost back with a <a href="#time-penalties-and-time-credits">race time adjustment</a>.</li></ul><p>Start lists you&#39;ve already printed or published don&#39;t move with the change; reprint and re-publish them.</p><h2 id="bulk-and-admin-fixes" tabindex="-1">Bulk and admin fixes <a class="header-anchor" href="#bulk-and-admin-fixes" aria-label="Permalink to &quot;Bulk and admin fixes&quot;">​</a></h2><p><strong>Marking all the no-shows DNS at the end.</strong> On the <strong>Competitors</strong> page, open <strong>Actions</strong> and choose <strong>Set competitors DNS…</strong>. Choose which statuses to sweep — <strong>None</strong> (never turned up) and <strong>On course (no radio punches)</strong> (an allocated start, but nothing — no radio start punch, start station read or radio control — saw them go) — and which classes. The dialog counts how many will be set to <strong>Did Not Start</strong> before you click <strong>Set DNS</strong>. Anyone who <strong>checked in</strong> and hasn&#39;t come back is always left out, for you to rule on one by one. This is the tidy-up that clears the On course count once you&#39;re sure everyone&#39;s accounted for. Once the check or start unit&#39;s memory has been read, <strong>No record of starting</strong> on the Station memory screen is a more exact list of non-starters. See <a href="./safety-check#marking-no-shows-as-dns-bulk">Safety check</a>.</p><p><strong>Finishing the event with people unsettled.</strong> <strong>Finish event</strong> checks first. If anybody has no settled result, <strong>Event not finalised</strong> lists them with the buttons that settle them in bulk — <strong>Set competitors DNS…</strong>, <strong>Set competitors overtime…</strong> for runners a radio control or the check saw go out, and <strong>Set radio finishes DNF or overtime…</strong> for runners whose only result is a radio finish. See <a href="./../after-the-event/results#settling-everyone-first">Settling everyone first</a>.</p><p><strong>Adding a late entry after the event has started.</strong> Classes and courses stay editable mid-event, so a late entry is a new competitor. Add them from <strong>Quick competitor actions</strong> on the <a href="./dashboard">dashboard</a> or from the <a href="./../event-setup/competitors-clubs-teams">Competitors list</a>, give them a class (and card), and they&#39;re in — a card they have already read, or radio punches it has already made, are picked up as soon as their card number is entered. See <a href="./late-entries">Late entries</a>.</p><p><strong>Someone turns up after you&#39;ve finished the event.</strong> Open the event and click <strong>Restart event</strong> in the app bar. It goes live again, so you can download their card and correct the result, then finish it a second time. This works on any later day too, and the late download gives the same result it would have on the day. See <a href="./dashboard#restarting-an-event-you-ve-already-finished">Restarting an event you&#39;ve already finished</a>.</p><p><strong>Who changed this?</strong> Every fix on this page is recorded. The competitor&#39;s <strong>Audit trail</strong> tab, and the event&#39;s <strong>Audit trail</strong> screen, show what was changed, when, and from which computer. See <a href="./../reference/audit-trail">Audit trail</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — why a competitor has the status and time Manager shows</li><li><a href="./card-download">Downloading cards</a> — the live fast fixes, the download detail dialog and manual downloads</li><li><a href="./../event-setup/start-times">Start times</a> — fixing a wrong or missing start</li><li><a href="./../event-setup/controls-and-radio-controls">Controls and radio controls</a> — time offsets, replacement codes, faulty controls</li><li><a href="./station-memory">Station Memory</a> — recovering punches from a control&#39;s backup memory</li><li><a href="./radio-punches">Radio punches</a> — suppressing, deleting and recovering radio punches</li><li><a href="./safety-check">Safety check: accounting for everyone</a> — the On course list and the DNS sweep</li><li><a href="./../reference/audit-trail">Audit trail</a> — what was changed, and by whom</li><li><a href="./live-standby">Live standby</a> — a second computer ready to take over</li><li><a href="./../reference/troubleshooting">Troubleshooting</a> — errors and unexpected behaviour</li></ul>',74)])])}const p=e(n,[["render",s]]);export{u as __pageData,p as default};
